<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import PageHeader from '../components/PageHeader.vue'
import LoadingState from '../components/LoadingState.vue'
import ErrorNotice from '../components/ErrorNotice.vue'
import MemoryCard from '../components/MemoryCard.vue'
import PreferenceOptions from '../components/PreferenceOptions.vue'
import DurationFields from '../components/DurationFields.vue'
import { deleteMemory, listMemories, submitFeedback, updateMemory } from '../services/memories'
import { errorMessage } from '../services/api'
import { useSessionStore } from '../stores/session'
import { useMemoryStore } from '../stores/memory'
import type { ConfirmationStatus, MemoryType, MemoryScope, MemoryItem } from '../types'

const session=useSessionStore(), memories=useMemoryStore()
const emit=defineEmits<{changed:[]}>()
const showFeedback=ref(false)
const preferredMinutes=ref<number|null>(null), maxMinutes=ref<number|null>(null)
withDefaults(defineProps<{ embedded?: boolean }>(), { embedded: false })
const busy=ref(false), saving=ref(false), error=ref(''), success=ref('')
const filters=reactive<{course:string;memory_type:MemoryType|'';confirmation_status:ConfirmationStatus|''}>({course:'',memory_type:'',confirmation_status:''})
const feedback=reactive<{scope:MemoryScope;course:string;knowledgePoint:string;content:string;feedback_type:MemoryType|'';explicit:boolean}>({scope:'course',course:'',knowledgePoint:'',content:'',feedback_type:'',explicit:false})

async function load(){busy.value=true;error.value='';try{const data=await listMemories({user_id:session.userId,course:filters.course||undefined,memory_type:filters.memory_type,confirmation_status:filters.confirmation_status,active:true});memories.items=data.items}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function submit(){saving.value=true;error.value='';success.value='';try{const data=await submitFeedback({user_id:session.userId,preferred_minutes:feedback.feedback_type==='task_preference'?preferredMinutes.value??undefined:undefined,max_minutes:feedback.feedback_type==='task_preference'?maxMinutes.value??undefined:undefined,scope:feedback.scope,course:feedback.scope==='global'?'':feedback.course,content:feedback.content,...(feedback.feedback_type?{feedback_type:feedback.feedback_type}:{}),...(feedback.feedback_type?{explicit:feedback.explicit}:{}),knowledge_point:feedback.scope==='knowledge_point'?feedback.knowledgePoint:undefined});success.value=`反馈已转为 ${data.memories[0]?.confirmation_status==='confirmed'?'已确认':'待确认'}记忆`;feedback.content='';showFeedback.value=false;await load();emit('changed')}catch(e){error.value=errorMessage(e)}finally{saving.value=false}}
async function setStatus(id:string,status:ConfirmationStatus){try{await updateMemory(id,{confirmation_status:status});await load();emit('changed')}catch(e){error.value=errorMessage(e)}}
async function edit(id:string,payload:Partial<MemoryItem>){try{await updateMemory(id,payload);await load();emit('changed')}catch(e){error.value=errorMessage(e)}}
async function remove(id:string){if(!window.confirm('确定删除这条记忆吗？系统会执行软删除并保留审计记录。'))return;try{await deleteMemory(id);await load();emit('changed')}catch(e){error.value=errorMessage(e)}}
onMounted(load)
</script>
<template><section class="memory-center" :class="{ embedded }"><PageHeader v-if="!embedded" eyebrow="MEMORY CENTER" title="让 Agent 记住真正有用的事" subtitle="待确认记忆不会影响计划；你始终可以确认、修改、拒绝或删除。"><span class="chip pending">{{ memories.pendingCount }} 条待确认</span></PageHeader>
  <div v-else class="embedded-heading"><div><p class="eyebrow">MEMORY CENTER</p><h2>我的反馈记忆</h2><p>只有已确认记忆才会影响 Agent；你可以随时确认、修改、归档或删除。</p></div><button type="button" class="btn btn-primary" @click="showFeedback=!showFeedback">{{ showFeedback?'收起':'+ 记录新偏好' }}</button></div>
  <form v-if="showFeedback || !embedded" class="feedback-box card panel" @submit.prevent="submit"><div><p class="eyebrow">TELL FLOW AGENT</p><h2>告诉 Flow Agent</h2><p class="muted">这里保存长期偏好；临时调整请在任务流或伴学中选择“仅本次使用”。</p></div><PreferenceOptions persistence="long_term" v-model:scope="feedback.scope" :course="feedback.course" :knowledge-point="feedback.knowledgePoint" :show-persistence="false" /><div v-if="feedback.scope!=='global'" class="feedback-scope"><div class="field"><label for="feedback-course">适用课程</label><input id="feedback-course" v-model.trim="feedback.course" required placeholder="例如：数据结构与算法" /></div><div v-if="feedback.scope==='knowledge_point'" class="field"><label for="feedback-point">知识点</label><input id="feedback-point" v-model.trim="feedback.knowledgePoint" required placeholder="例如：BFS" /></div></div><div class="field"><label for="feedback">你的反馈</label><textarea id="feedback" v-model.trim="feedback.content" required rows="3" placeholder="例如：先给我看例子，再讲定义。"/></div><div class="feedback-options"><div class="field"><label for="type">记忆类型</label><select id="type" v-model="feedback.feedback_type"><option value="">自动判断类型</option><option value="task_preference">任务偏好</option><option value="explanation_preference">解释偏好</option><option value="recovery_experience">恢复经验</option><option value="review_schedule">复习计划</option></select></div><label class="explicit"><input v-model="feedback.explicit" type="checkbox" :disabled="!feedback.feedback_type"/>这是我的明确偏好</label><button class="btn btn-primary" :disabled="saving||!feedback.content">{{ saving?'正在保存…':'保存为记忆 →' }}</button></div><DurationFields v-if="feedback.feedback_type==='task_preference'" v-model:preferred="preferredMinutes" v-model:maximum="maxMinutes" :disabled="saving" /><p class="muted">同范围的新时长偏好会替换整组旧时长设置；首选和上限需要保留时请一起填写。</p></form>
  <div v-if="success" class="notice success">{{ success }}</div><ErrorNotice v-if="error" :message="error" @retry="load"/>
  <div class="section-title"><h2>记忆列表 <span class="list-count">{{ memories.items.length }}</span></h2><button class="link-button" @click="load">刷新</button></div>
  <div class="filters card"><div class="field"><label for="filter-course">课程</label><input id="filter-course" v-model.trim="filters.course" placeholder="全部课程" @change="load"/></div><div class="field"><label for="filter-type">类型</label><select id="filter-type" v-model="filters.memory_type" @change="load"><option value="">全部类型</option><option value="task_preference">任务偏好</option><option value="explanation_preference">解释偏好</option><option value="knowledge_state">知识状态</option><option value="recovery_experience">恢复经验</option><option value="review_schedule">复习计划</option></select></div><div class="field"><label for="filter-status">状态</label><select id="filter-status" v-model="filters.confirmation_status" @change="load"><option value="">全部状态</option><option value="pending">待确认</option><option value="confirmed">已确认</option><option value="rejected">已拒绝</option><option value="archived">已归档</option></select></div></div>
  <LoadingState v-if="busy" text="正在读取你的记忆…"/><div v-else-if="!memories.items.length" class="card panel empty"><h3>没有符合条件的记忆</h3><p class="muted">提交一条反馈，或调整上方筛选条件。</p></div><div v-else class="memory-grid"><MemoryCard v-for="item in memories.items" :key="item.id" :memory="item" @update="setStatus(item.id,$event)" @edit="edit(item.id,$event)" @remove="remove(item.id)"/></div>
</section></template>
<style scoped>
.embedded-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:24px}.embedded-heading .eyebrow{font-size:9px;letter-spacing:.1em;color:#7b8cb0;margin:0 0 8px}.embedded-heading h2{margin:0 0 9px;color:#283965;font-size:18px}.embedded-heading p:last-child{margin:0;color:#6b7da2;font-size:11px;line-height:1.9}.embedded-heading>.btn{flex-shrink:0;min-height:36px;padding:9px 14px;font-size:11px;box-shadow:none;background:linear-gradient(110deg,#3cb9d2,#8170df)}.feedback-scope{display:grid;grid-template-columns:1fr 1fr;gap:16px}.list-count{margin-left:6px;color:#7b8cb0;font-size:12px;font-weight:400}.embedded .feedback-box{border-radius:16px;background:#f8faff;box-shadow:none;margin-bottom:20px}.embedded .feedback-box h2{font-size:15px}.embedded .feedback-box .eyebrow{font-size:9px}.embedded .feedback-box .muted{font-size:11px}.embedded .section-title{margin:22px 0 14px}.embedded .section-title h2{font-size:14px;color:#627093}.embedded .filters{border-radius:13px;background:#f8faff;border-color:#edf0f8;box-shadow:none}.embedded .field label{font-size:11px;color:#65799f}.embedded .field input,.embedded .field select,.embedded .field textarea{font-size:12px}.embedded .memory-grid{gap:14px}.embedded :deep(.memory-card){border-radius:16px;box-shadow:none;border-color:#e8ecf6}.embedded :deep(.memory-card .content){font-size:13px;font-weight:500;color:#435c83}.embedded :deep(.memory-card .id-button){display:none}.embedded :deep(.memory-card .actions .btn){font-size:10px;min-height:30px;padding:6px 10px;border-radius:9px}.embedded .empty{box-shadow:none;border:1px dashed #e4e9f5;border-radius:16px}.embedded .empty h3{font-size:13px;font-weight:500;color:#63779f}.embedded .empty p{font-size:11px;color:#7a8bad}@media(max-width:650px){.embedded-heading{align-items:flex-start;gap:10px}.embedded-heading>.btn{padding:8px 10px;font-size:10px}.feedback-scope{grid-template-columns:1fr}}
.feedback-box{display:grid;gap:18px}.feedback-box h2{margin:4px 0 7px}.feedback-box p{margin-bottom:0}.feedback-options{display:grid;grid-template-columns:1fr auto auto;gap:16px;align-items:end}.explicit{display:flex;align-items:center;gap:8px;min-height:42px;color:var(--muted);font-size:13px}.explicit input{accent-color:var(--brand)}.filters{padding:15px;display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.memory-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px;margin-top:18px}.empty{text-align:center;margin-top:18px}@media(max-width:850px){.memory-grid{grid-template-columns:1fr}}@media(max-width:650px){.feedback-options,.filters{grid-template-columns:1fr}.explicit{min-height:0}}</style>
